// P(fire) = sigmoid( base + sum of the leaf reached in every tree ), on the raw sensor values
static inline float xgb_predict_proba(const float *x) {
  float z = XGB_BASE_MARGIN;
  for (int t = 0; t < XGB_N_TREES; t++) {
    const XgbNode *n = &XGB_NODES[XGB_TREE_ROOT[t]];
    while (n->feature >= 0) n = &XGB_NODES[x[n->feature] < n->value ? n->left : n->right];
    z += n->value;
  }
  return 1.0f / (1.0f + expf(-z));
}
